input.content:
import { readFileSync, writeFileSync } from 'node:fs';
const files = ['b1','b2','b3','b4','b5','b6','b7','b8','b9','b10','b11','b12','b13'];
const seen = new Set();
const out = [];
for (const f of files) {
  for (const line of readFileSync(`/tmp/p/${f}.jsonl`,'utf8').split('\n')) {
    if (line.trim()==='') continue;
    const v = JSON.parse(line);
    const text = typeof v === 'string' ? v : v.text;
    if (seen.has(text)) continue;
    seen.add(text);
    if (text.startsWith('-')) { continue; }   // argparse rejects a value starting with '-'
    out.push(JSON.stringify(text));
  }
}
writeFileSync('/workspace/harness/cases/03-headers-hr.jsonl', out.join('\n')+'\n');
console.log('kept', out.length, 'dropped(dash-leading or dup)', seen.size - out.length);

input.command:
cd /tmp/p && node -e "
const fs=require('fs');
const existing=new Set(fs.readFileSync('/workspace/harness/cases/03-headers-hr.jsonl','utf8').split('\n').filter(l=>l.trim()).map(l=>JSON.parse(l)));
const add=[];
for(const f of ['b14','b15']){
  for(const l of fs.readFileSync('/tmp/p/'+f+'.jsonl','utf8').split('\n')){
    if(!l.trim())continue; const v=JSON.parse(l); const t=typeof v==='string'?v:v.text;
    if(existing.has(t)||t.startsWith('-'))continue; existing.add(t); add.push(JSON.stringify(t));
  }
}
fs.appendFileSync('/workspace/harness/cases/03-headers-hr.jsonl', add.join('\n')+'\n');
console.log('appended',add.length,'total',existing.size);
"
